<?php if(current_user()) redirect(app_url('index.php')); $flashes=take_flashes(); $token=(string)($_GET['token']??''); $valid=preg_match('/^[a-f0-9]{64}$/',$token)===1; if($valid){$q=db()->prepare('SELECT id FROM password_resets WHERE token_hash=? AND used_at IS NULL AND expires_at>NOW()');$q->execute([hash('sha256',$token)]);$valid=(bool)$q->fetchColumn();} ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Choose new password · Makahupay</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="<?=h(app_url('assets/css/app.css'))?>" rel="stylesheet"></head><body><div class="login-wrap"><div class="login-brand"><div class="brand-mark"><i class="bi bi-flower1"></i></div><strong><?=h(setting('business_name','Makahupay Reflex & Massage'))?></strong></div><div class="login-card"><h1>Choose a new password</h1><?php foreach($flashes as $f):?><div class="alert alert-<?=h($f['type'])?> py-2"><?=h($f['message'])?></div><?php endforeach;?><?php if(!$valid):?><div class="alert alert-warning">This reset link is invalid or has expired. Request a new link.</div><a href="<?=h(app_url('index.php?page=forgot'))?>" class="btn btn-primary w-100">Request new link</a><?php else:?><p class="text-muted">Use at least 12 characters.</p><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="perform_reset"><input type="hidden" name="token" value="<?=h($token)?>"><label class="form-label">New password</label><input class="form-control mb-3" type="password" name="password" minlength="12" required autocomplete="new-password"><button class="btn btn-primary w-100">Update password</button></form><?php endif;?></div></div></body></html>
